package app.prismkeys;
import android.app.Activity;
import android.os.Bundle;
import android.content.Intent;
import android.provider.Settings;
import android.view.inputmethod.*;
import android.webkit.*;
import android.widget.*;

public class MainActivity extends Activity {
 WebView web; EditText test;TextView status;
 InputMethodManager manager(){return (InputMethodManager)getSystemService(INPUT_METHOD_SERVICE);}
 boolean enabled(){for(InputMethodInfo info:manager().getEnabledInputMethodList())if(getPackageName().equals(info.getPackageName()))return true;return false;}
 void updateStatus(){if(status==null)return;String current=Settings.Secure.getString(getContentResolver(),Settings.Secure.DEFAULT_INPUT_METHOD);status.setText(!enabled()?"1. Enable Prism, then choose it.":current!=null&&current.startsWith(getPackageName()+"/")?"Prism selected · tap the test field to type":"Prism enabled · tap Choose to switch");}
 void choose(){if(!enabled()){Toast.makeText(this,"Enable Prism Keys in the keyboard list first",Toast.LENGTH_LONG).show();startActivity(new Intent(Settings.ACTION_INPUT_METHOD_SETTINGS));return;}test.requestFocus();manager().showSoftInput(test,InputMethodManager.SHOW_IMPLICIT);test.postDelayed(()->{try{manager().showInputMethodPicker();}catch(Exception e){startActivity(new Intent(Settings.ACTION_INPUT_METHOD_SETTINGS));}},250);}
 public void onCreate(Bundle b){super.onCreate(b);PrismRuntime.ensure(this);try{startForegroundService(new Intent(this,PrismServerService.class));}catch(Exception e){Toast.makeText(this,"Local server works; background service could not start",Toast.LENGTH_LONG).show();}LinearLayout layout=new LinearLayout(this);layout.setOrientation(1);status=new TextView(this);status.setPadding(16,8,16,4);status.setTextSize(12);layout.addView(status);LinearLayout buttons=new LinearLayout(this);
 Button enable=new Button(this);enable.setText("Enable");enable.setOnClickListener(v->startActivity(new Intent(Settings.ACTION_INPUT_METHOD_SETTINGS)));buttons.addView(enable,new LinearLayout.LayoutParams(0,-2,1));Button choose=new Button(this);choose.setText("Choose");choose.setOnClickListener(v->choose());buttons.addView(choose,new LinearLayout.LayoutParams(0,-2,1));Button file=new Button(this);file.setText("Import");file.setOnClickListener(v->{Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT);pick.addCategory(Intent.CATEGORY_OPENABLE);pick.setType("text/*");startActivityForResult(pick,42);});buttons.addView(file,new LinearLayout.LayoutParams(0,-2,1));Button server=new Button(this);server.setText("Server");server.setOnClickListener(v->serverSettings());buttons.addView(server,new LinearLayout.LayoutParams(0,-2,1));layout.addView(buttons);
 test=new EditText(this);test.setSingleLine(true);test.setHint("Tap here to test Prism keyboard");test.setTextSize(14);layout.addView(test);layout.setFocusableInTouchMode(true);layout.requestFocus();web=new WebView(this);configure(web);web.setWebViewClient(new WebViewClient(){public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){return asset(v,r);}public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return navigate(v,r);}public void onPageFinished(WebView v,String u){if(local(u)){v.evaluateJavascript("document.body.classList.add('launcher-mode')",null);PrismRuntime.connect(v);}}});layout.addView(web,new LinearLayout.LayoutParams(-1,0,1));setContentView(layout);getWindow().setSoftInputMode(android.view.WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|android.view.WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);web.loadUrl(PrismRuntime.URL);updateStatus();}
 protected void onResume(){super.onResume();updateStatus();}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=42||result!=RESULT_OK||data==null)return;try{java.io.InputStream input=getContentResolver().openInputStream(data.getData());java.io.ByteArrayOutputStream output=new java.io.ByteArrayOutputStream();byte[] buffer=new byte[4096];int n;while((n=input.read(buffer))!=-1){if(output.size()+n>1000000)throw new java.io.IOException("File too large (1MB limit)");output.write(buffer,0,n);}input.close();String text=new String(output.toByteArray(),java.nio.charset.StandardCharsets.UTF_8);web.evaluateJavascript("setText("+org.json.JSONObject.quote(text)+");toast('File loaded · Save context to keep it');",null);}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}}
 static WebResourceResponse asset(WebView view,WebResourceRequest req){if(!local(req.getUrl().toString())||!"GET".equals(req.getMethod()))return null;String path=req.getUrl().getPath();String file="/".equals(path)?"index.html":path.substring(1);if(!file.equals("index.html")&&!file.equals("companion.js")&&!file.equals("keyboard-ui.js")&&!file.equals("original.html")&&!file.equals("synthia-core.js"))return null;try{return new WebResourceResponse(file.endsWith(".js")?"text/javascript":"text/html","UTF-8",openAsset(view.getContext(),file));}catch(Exception e){return null;}}
 static java.io.InputStream openAsset(android.content.Context c,String name)throws java.io.IOException{java.io.File override=PrismRuntime.override(c,name);return override.isFile()?new java.io.FileInputStream(override):c.getAssets().open(name);}
 void serverSettings(){LinearLayout fields=new LinearLayout(this);fields.setOrientation(1);int pad=(int)(16*getResources().getDisplayMetrics().density);fields.setPadding(pad,0,pad,0);TextView info=new TextView(this);info.setText("Server and workspace MCP run inside Prism. Add a model for AI. Connect your proot/VM bridge for Python and packages.");fields.addView(info);TextView runtimeState=new TextView(this);runtimeState.setText("Embedded Synthia 5.8: "+PrismRuntime.hoverState());fields.addView(runtimeState);Button setup=new Button(this);setup.setText("Synthia identity and tools");setup.setOnClickListener(v->startActivity(new Intent(this,SynthiaSetupActivity.class)));fields.addView(setup);String[][] items={{"apiBase","AI API base","https://api.openai.com/v1"},{"model","Model","gpt-4.1-mini"},{"apiKey","AI API key",""},{"githubToken","GitHub token",""},{"googleKey","Google API key",""},{"googleCx","Google search engine ID",""},{"linuxMode","Linux adapter: prism, synthai2, or synthia","prism"},{"linuxUrl","Proot/VM bridge URL",""},{"linuxToken","Linux bridge token",""},{"synthiaMode","Synthia mode: hover or operator","hover"},{"synthiaUrl","Synthia base URL (embedded Hover default)",""},{"synthiaToken","Synthia Operator token",""},{"mcpUrl","External MCP HTTP URL",""},{"mcpToken","External MCP token",""}};java.util.Map<String,EditText> edits=new java.util.LinkedHashMap<>();for(String[] item:items){TextView label=new TextView(this);label.setText(item[1]);fields.addView(label);EditText edit=new EditText(this);boolean secret=item[0].toLowerCase().contains("key")||item[0].toLowerCase().contains("token");edit.setSingleLine(true);if(secret){edit.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);edit.setHint(PrismRuntime.get(item[0],"").isEmpty()?"Not configured":"Configured; leave blank to keep");}else edit.setText(PrismRuntime.get(item[0],item[2]));fields.addView(edit);edits.put(item[0],edit);}TextView endpoint=new TextView(this);PrismServer runtime=PrismRuntime.ensure(this);endpoint.setText("Local MCP: "+PrismRuntime.URL+"mcp\nServer token (for trusted MCP clients): "+(runtime==null?"unavailable":runtime.token));endpoint.setTextIsSelectable(true);fields.addView(endpoint);ScrollView scroll=new ScrollView(this);scroll.addView(fields);new android.app.AlertDialog.Builder(this).setTitle("Built-in server").setView(scroll).setPositiveButton("Save",(d,w)->{try{for(java.util.Map.Entry<String,EditText> entry:edits.entrySet()){String value=entry.getValue().getText().toString().trim();if(value.isEmpty()&&(entry.getKey().toLowerCase().contains("key")||entry.getKey().toLowerCase().contains("token")))continue;PrismRuntime.set(entry.getKey(),value);}PrismRuntime.connect(web);Toast.makeText(this,"Server settings saved on device",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}}).setNeutralButton("Restore UI",(d,w)->{PrismRuntime.restoreUI(this);web.reload();}).setNegativeButton("Cancel",null).show();}
 static boolean local(String url){try{android.net.Uri u=android.net.Uri.parse(url);return "http".equals(u.getScheme())&&"127.0.0.1".equals(u.getHost())&&u.getPort()==PrismRuntime.PORT;}catch(Exception e){return false;}}
 static boolean navigate(WebView v,WebResourceRequest req){if(local(req.getUrl().toString()))return false;if(req.isForMainFrame()&&"https".equals(req.getUrl().getScheme())){try{Intent i=new Intent(Intent.ACTION_VIEW,req.getUrl());i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);v.getContext().startActivity(i);}catch(Exception e){}}return true;}
 static void configure(WebView web){web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.setWebViewClient(new WebViewClient(){public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){return asset(v,r);}public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest req){return navigate(v,req);}});}
}
